 34	fn monthly_totals(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
 35	    let mut totals = BTreeMap::new();
 36	    for entry in entries {
 37	        if !entry.billable || entry.stop.is_none() || entry.duration < 0 {
 38	            continue;
 39	        }
 40	        let month = entry.start.with_timezone(&Utc).format("%Y-%m").to_string();
 41	        *totals.entry(month).or_insert(0) += billable_seconds(entry);
 42	    }
 43	    totals
 44	}
