 46	fn format_monthly_invoice(entries: &[TimeEntry]) -> String {
 47	    let totals = monthly_totals(entries);
 48	    if totals.is_empty() {
 49	        return "(no data)\n".to_string();
 50	    }
 51	
 52	    let mut output = String::new();
 53	    let mut total = 0;
 54	    for (month, seconds) in totals {
 55	        output.push_str(&format!("{month}  {seconds}s\n"));
 56	        total += seconds;
 57	    }
 58	    output.push_str(&format!("Total  {total}s\n"));
 59	    output
 60	}
